import { Component, OnInit } from '@angular/core';
import { Job } from 'src/app/landing/models/job';
import { JobService } from 'src/app/service/job/job.service';

@Component({
  selector: 'app-saved-jobs',
  templateUrl: './saved-jobs.component.html',
  styleUrls: ['./saved-jobs.component.css']
})
export class SavedJobsComponent implements OnInit {

  savedJobs: Job[] = [];
  totalSavedJobs = 0;

  constructor(private jobService: JobService) {}

  ngOnInit(): void {
    const jobSeekerId = Number(localStorage.getItem('id'));
    this.getAllSavedJobs(jobSeekerId);
  }

  getAllSavedJobs(jobSeekerId: number): void {
    this.jobService.getSavedJobs(jobSeekerId).subscribe({
      next: (result) => {
        this.savedJobs = result;
        this.totalSavedJobs = this.savedJobs.length;
      },
      error: (err) => { console.log(err); }
    });
  }

  removeSavedJob(jobId: string | number): void {
    const id = Number(jobId);
    const jobSeekerId = Number(localStorage.getItem('id'));

    this.jobService.removeSavedJob(id, jobSeekerId).subscribe({
      next: () => {
        this.savedJobs = this.savedJobs.filter(job => Number(job.jobId) !== id);
        this.totalSavedJobs = this.savedJobs.length;
      },
      error: (err) => { console.log(err); }
    });
  }
}
<div class="page">
<app-header variant="seeker"></app-header>
<div class="app-shell">
<app-sidebar variant="seeker"></app-sidebar>
<main class="main">

<div class="page-title">Saved Jobs</div>
<div class="page-sub">{{totalSavedJobs}} roles you've bookmarked to apply to later.</div>
<div class="table-wrap">
  <table>
    <thead>
      <tr>
        <th>Role</th>
        <th>Company</th>
        <th>Salary</th>
        <th></th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let job of savedJobs">
        <td>{{job.jobTitle}}</td>
        <td>{{job.companyName}}</td>
        <td>&#8377;{{job.salary}}</td>
        <td class="actions">
          <a [routerLink]="['/job/view-job', job.jobId]">View</a>
          <a class="danger" style="cursor:pointer;" (click)="removeSavedJob(job.jobId)">Remove</a>
        </td>
      </tr>
    </tbody>
  </table>
</div>

</main>
</div>
</div>
